import {scenarios, calculate} from './model.js';
import {mountNavigation} from './navigation.js';
import {mountPresentation, enhanceFinance} from './presentation.js';
import {mountStory} from './story.js';

const app = document.querySelector('#app');
const params = new URLSearchParams(location.search);
let lang = params.get('lang') === 'ar' ? 'ar' : 'en';
let audience = ['investor','partner','builder'].includes(params.get('view')) ? params.get('view') : 'investor';
let country = params.get('country') || 'ae';
let sector = params.get('sector') || 'qsr';
let scenario = params.get('case') === 'downside' ? 'downside' : 'base';
let layout = params.get('layout') === 'document' ? 'document' : 'chapters';
let inputs = {...scenarios[scenario]};
let cleanupNavigation=()=>{},cleanupPresentation=()=>{},cleanupStory=()=>{};
let journeyStep = 0, sourceLimit = 8, backlogLimit = 8;
let sourceQuery = '', backlogQuery = '', backlogScope = 'all', backlogPriority = 'all';
let research, evidence, backlog;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tx = value => typeof value === 'object' && value !== null ? value[lang] ?? value.en ?? '' : value;
const l = (en,ar) => lang === 'ar' ? ar : en;
const money = (n, digits=0) => new Intl.NumberFormat(lang==='ar'?'ar-AE':'en-AE',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(n);
const citations = ids => (ids || []).length ? `<button type="button" class="citation" data-sources="${esc(ids.join(','))}" aria-label="${l('Inspect sources','افحص المصادر')} ${esc(ids.join(', '))}">[${esc(ids.join(' · '))}]</button>` : '';
const label = (en,ar) => `<span class="fact-label">${l(en,ar)}</span>`;
const sourceClaim = s => s.supporting_fact ?? s.supported_fact ?? s.supports ?? s.claim ?? s.source_version ?? '';
const sourceLimits = s => s.limitations ?? s.uncertainty ?? s.contradictions ?? 'Scope is limited to the supported claim. Reconfirm before implementation.';
const modelFields = [
  ['liftPercent','Repeat-order lift (%)','زيادة الطلبات المتكررة (%)',0,100,.5],
  ['notificationOptInPercent','Orders with alerts (%)','الطلبات المفعّل لها تنبيه (%)',0,100,1],
  ['landedMessageCost','Message cost (AED)','تكلفة الرسالة (درهم)',0,5,.001],
  ['monthlyFee','Monthly fee (AED)','الاشتراك الشهري (درهم)',0,3000,1],
  ['supportHours','Support hours / location','ساعات الدعم لكل موقع',0,20,.25],
  ['churnPercent','Monthly location churn (%)','تسرب المواقع الشهري (%)',0,100,.5],
  ['newLocationsPerMonth','New locations / month','مواقع جديدة شهريًا',0,1000,1]
];
for (const [key,,,min,max] of modelFields) {
  const value = params.get(`m_${key}`);
  if (value !== null && value.trim() !== '' && Number.isFinite(+value) && +value >= min && +value <= max) inputs[key] = +value;
}

function updateURL() {
  const url = new URL(location.href);
  url.search = '';
  for (const [key,value] of Object.entries({lang,view:audience,country,sector,case:scenario})) url.searchParams.set(key,value);
  if(layout==='document')url.searchParams.set('layout','document');
  for (const [key] of modelFields) if (inputs[key] !== scenarios[scenario][key]) url.searchParams.set(`m_${key}`,inputs[key]);
  history.replaceState(null,'',url);
}
function announce(text) { document.querySelector('#announcer').textContent = text; }

function restoreURLState(){
  const p=new URLSearchParams(location.search);
  const next={lang:p.get('lang')==='ar'?'ar':'en',audience:['investor','partner','builder'].includes(p.get('view'))?p.get('view'):'investor',country:research.countries.some(c=>c.id===p.get('country'))?p.get('country'):'ae',sector:research.sectors.some(s=>s.id===p.get('sector'))?p.get('sector'):'qsr',scenario:p.get('case')==='downside'?'downside':'base',layout:p.get('layout')==='document'?'document':'chapters'};
  const nextInputs={...scenarios[next.scenario]};
  for(const[key,,,min,max]of modelFields){const raw=p.get(`m_${key}`);if(raw!==null&&raw.trim()!==''&&Number.isFinite(+raw)&&+raw>=min&&+raw<=max)nextInputs[key]=+raw;}
  const old=JSON.stringify({lang,audience,country,sector,scenario,layout,inputs});
  const fresh=JSON.stringify({...next,inputs:nextInputs});
  if(old===fresh)return false;
  ({lang,audience,country,sector,scenario,layout}=next);inputs=nextInputs;render();return true;
}

const copy = {
  investor:{title:{en:'For investors',ar:'للمستثمرين'},text:{en:'Start with merchant value, test the cash model, then inspect the evidence gates that control capital.',ar:'ابدأ بقيمة المنتج للتاجر، اختبر التدفقات النقدية، ثم افحص الأدلة المطلوبة قبل صرف رأس المال.'},link:'economics',cta:{en:'Inspect the economics ↗',ar:'افحص الاقتصاديات ↗'}},
  partner:{title:{en:'For operating partners',ar:'للشركاء التشغيليين'},text:{en:'Start with one country, one workflow and one connector. A paid field test must establish value and integration rights.',ar:'ابدأ بدولة ومسار عمل وموصل واحد. تجربة ميدانية مدفوعة تثبت القيمة وصلاحيات التكامل.'},link:'markets',cta:{en:'Choose a pilot cell ↗',ar:'اختر خلية التجربة ↗'}},
  builder:{title:{en:'For collaborators',ar:'للمتعاونين'},text:{en:'Start with domain boundaries, delivery gates and acceptance criteria. Scope expands only after the current slice passes.',ar:'ابدأ بحدود النظام وبوابات التسليم ومعايير القبول. يتسع النطاق بعد نجاح الجزء الحالي.'},link:'blueprint',cta:{en:'Explore the blueprint ↗',ar:'استكشف مخطط التنفيذ ↗'}}
};

